SELECT id AS id, view_id AS viewId, cfg_id AS cfgId, view_name AS viewName, view_type AS viewType, tpl_type AS tplType, tpl_id AS tplId, ctg_id AS ctgId, tpl_name AS tplName, tpl_owner AS tplOwner, view_owner AS viewOwner, tpl_created_time AS tplCreatedTime, is_public_domain AS isPublicDomain, is_vip_owner AS isVipOwner, is_portal AS isPortal, is_owner_all_left AS isOwnerAllLeft, days_no_visit AS daysNoVisit, last_visit_time AS lastVisitTime FROM ssm_governance_view_label
WHERE id > #{lastId}
ORDER BY id LIMIT #{pageSize}

